sealed class CoreException: kotlin.Exception() {
    
    class Discovery(
        
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Negotiation(
        
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Transport(
        
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Protocol(
        
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Http(
        
        val `status`: kotlin.UShort, 
        
        val `path`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "status=${ `status` }, path=${ `path` }"
    }
    
    class Api(
        
        val `status`: kotlin.UShort, 
        
        val `code`: kotlin.String, 
        
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "status=${ `status` }, code=${ `code` }, detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        

        return when(buf.getInt()) {
            1 -> CoreException.Discovery(
                FfiConverterString.read(buf),
                )
            2 -> CoreException.Negotiation(
                FfiConverterString.read(buf),
                )
            3 -> CoreException.Transport(
                FfiConverterString.read(buf),
                )
            4 -> CoreException.Protocol(
                FfiConverterString.read(buf),
                )
            5 -> CoreException.Http(
                FfiConverterUShort.read(buf),
                FfiConverterString.read(buf),
                )
            6 -> CoreException.Api(
                FfiConverterUShort.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreException): ULong {
        return when(value) {
            is CoreException.Discovery -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CoreException.Negotiation -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CoreException.Transport -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CoreException.Protocol -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CoreException.Http -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`status`)
                + FfiConverterString.allocationSize(value.`path`)
            )
            is CoreException.Api -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`status`)
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.Discovery -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CoreException.Negotiation -> {
                buf.putInt(2)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CoreException.Transport -> {
                buf.putInt(3)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CoreException.Protocol -> {
                buf.putInt(4)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CoreException.Http -> {
                buf.putInt(5)
                FfiConverterUShort.write(value.`status`, buf)
                FfiConverterString.write(value.`path`, buf)
                Unit
            }
            is CoreException.Api -> {
                buf.putInt(6)
                FfiConverterUShort.write(value.`status`, buf)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * v2 单流状态（`qaqh_client::V2StreamStatus` 的窄映射；`ReconnectReason`
 * 序列化成 `lagged:<n>` / `stream_terminated:<code>` 字符串）。
 */
sealed class StreamStatus {
    
    object Connecting : StreamStatus()
    
    
    data class Open(
        val `serverEpoch`: kotlin.String, 
        val `cursor`: kotlin.String?) : StreamStatus()
        
    {
        

        companion object
    }
    
    data class Reconnecting(
        val `retryMs`: kotlin.ULong, 
        val `reason`: kotlin.String?) : StreamStatus()
        
    {
        

        companion object
    }
    
    data class Closed(
        val `reason`: kotlin.String) : StreamStatus()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeStreamStatus : FfiConverterRustBuffer<StreamStatus>{
    override fun read(buf: ByteBuffer): StreamStatus {
        return when(buf.getInt()) {
            1 -> StreamStatus.Connecting
            2 -> StreamStatus.Open(
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            3 -> StreamStatus.Reconnecting(
                FfiConverterULong.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            4 -> StreamStatus.Closed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: StreamStatus): ULong = when(value) {
        is StreamStatus.Connecting -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is StreamStatus.Open -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`serverEpoch`)
                + FfiConverterOptionalString.allocationSize(value.`cursor`)
            )
        }
        is StreamStatus.Reconnecting -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`retryMs`)
                + FfiConverterOptionalString.allocationSize(value.`reason`)
            )
        }
        is StreamStatus.Closed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: StreamStatus, buf: ByteBuffer) {
        when(value) {
            is StreamStatus.Connecting -> {
                buf.putInt(1)
                Unit
            }
            is StreamStatus.Open -> {
                buf.putInt(2)
                FfiConverterString.write(value.`serverEpoch`, buf)
                FfiConverterOptionalString.write(value.`cursor`, buf)
                Unit
            }
            is StreamStatus.Reconnecting -> {
                buf.putInt(3)
                FfiConverterULong.write(value.`retryMs`, buf)
                FfiConverterOptionalString.write(value.`reason`, buf)
                Unit
            }
            is StreamStatus.Closed -> {
                buf.putInt(4)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * 外推事件回调（Rust 后台线程 → JVM；Kotlin 侧自行 marshal 到 UI 线程）。
 */
public interface CoreHandlers {
    
    /**
     * 单流事件帧；`event_json` 是 `SessionEvent`（tag="type" snake_case）。
     */
    fun `onEvent`(`sessionId`: kotlin.String, `seq`: kotlin.ULong, `eventJson`: kotlin.String)
    
