    }
}

/**
 * The ffiConverter which transforms the Callbacks in to handles to pass to Rust.
 *
 * @suppress
 */
public object FfiConverterTypeCoreHandlers: FfiConverterCallbackInterface<CoreHandlers>()




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}








        /**
         * 连接 daemon（remote 直连模式）：open 租约 + 起续租/attach 重放后台任务。
         *
         * 之后调用方负责 `attach(seed) → activate_stream(seed)` 编排。
         */
    @Throws(CoreException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
     suspend fun `connectClient`(`baseUrl`: kotlin.String, `deviceToken`: kotlin.String, `tlsFp`: kotlin.String?, `handlers`: CoreHandlers) : QaqhClient {
        return uniffiRustCallAsync(
        UniffiLib.uniffi_qaqh_ffi_fn_func_connect_client(
        FfiConverterString.lower(`baseUrl`),
        FfiConverterString.lower(`deviceToken`),
        FfiConverterOptionalString.lower(`tlsFp`),
        FfiConverterTypeCoreHandlers.lower(`handlers`),),
        { future, callback, continuation -> UniffiLib.ffi_qaqh_ffi_rust_future_poll_u64(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_qaqh_ffi_rust_future_complete_u64(future, continuation) },
        { future -> UniffiLib.ffi_qaqh_ffi_rust_future_free_u64(future) },
        // lift function
        { FfiConverterTypeQaqhClient.lift(it) },
        // Error FFI converter
        CoreException.ErrorHandler,
    )
    }

